var i=`0197-trinxat`;var n=`world-0197`;var a=`AD`;var o=`southern-europe`;var r=4;var s=54;var l={en:`Trinxat`,ua:`Тріншат`};var u={en:`A classic dish from Andorra, featuring potato, white cabbage, bacon, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Андорра. Основні складники: картопля, білоголова капуста, бекон, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`potato`,600,`g`],[`white-cabbage`,460,`g`],[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`bacon`,180,`g`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`unsalted-butter`,40,`g`]]}];var g={slug:i,id:n,country:`AD`,region:o,servings:4,minutes:54,title:l,text:u,steps:d};export{a as country,g as default,n as id,s as minutes,o as region,r as servings,i as slug,d as steps,u as text,l as title};